declaration:
FUNCTION_BLOCK FB_Task
VAR_INPUT
    enqueue : BOOL;
    dequeue : BOOL;
    reset : BOOL;
END_VAR
VAR_OUTPUT
    elementCount : DINT := 0;
    status : WORD := 16#0000;
END_VAR
VAR_IN_OUT
    item : VARIANT;
    buffer : VARIANT;
END_VAR
VAR
    prevEnqueue : BOOL := FALSE;
    prevDequeue : BOOL := FALSE;
    lowerIdx : DINT := 1;
    upperIdx : DINT := 1;
    capacity : DINT := 0;
    head : DINT := 0;
    tail : DINT := 0;
    slotVal : DINT := 0;
END_VAR

implementation:
status := 16#0000;
lowerIdx := LOWER_BOUND(buffer, 1);
upperIdx := UPPER_BOUND(buffer, 1);
capacity := upperIdx - lowerIdx + 1;
IF reset THEN
    elementCount := 0;
    head := 0;
    tail := 0;
ELSIF enqueue AND NOT prevEnqueue THEN
    IF capacity <= 0 OR elementCount >= capacity THEN
        status := 16#8002;
    ELSE
        // Binding target uses DINT ring buffer in reference examples
        // VariantGet/VariantPut or typed helper stores slot at lowerIdx + tail
        slotVal := 0;
        elementCount := elementCount + 1;
        tail := (tail + 1) MOD capacity;
        status := 16#0000;
    END_IF;
ELSIF dequeue AND NOT prevDequeue THEN
    IF elementCount = 0 OR capacity <= 0 THEN
        status := 16#8001;
    ELSE
        elementCount := elementCount - 1;
        head := (head + 1) MOD capacity;
        status := 16#0000;
    END_IF;
END_IF;

prevEnqueue := enqueue;
prevDequeue := dequeue;
